-- Kalo · sal y jugo de limón (para añadirle al agua y a lo que sea), carne de cerdo, y «marrano» encuentra todo lo de cerdo
alter table public.alimentos drop constraint if exists alimentos_categoria_check;
alter table public.alimentos add constraint alimentos_categoria_check check (categoria in ('frutas','verduras','carbohidratos','proteinas','lacteos','grasas','bebidas','condimentos'));
insert into public.alimentos (id, nombre, sinonimos, categoria, fuente, por_100g, porcion_base, porciones, foto_url, busqueda) values ('sal', 'Sal', array['sal de cocina', 'sal marina']::text[], 'condimentos', 'Sal de mesa. USDA sr_legacy · 173468', '{"fibra_g": 0.0, "hierro_mg": 0.33, "magnesio_mg": 1.0, "fosforo_mg": 0.0, "sodio_mg": 38758.0, "cobre_mg": 0.03, "manganeso_mg": 0.1, "grasa_sat_g": 0.0, "vit_c_mg": 0.0, "b1_mg": 0.0, "b2_mg": 0.0, "folato_ug": 0.0, "b12_ug": 0.0, "colesterol_mg": 0.0, "proteina_g": 0.0, "grasa_g": 0.0, "carbos_g": 0.0, "kcal": 0.0, "calcio_mg": 24.0, "potasio_mg": 8.0, "zinc_mg": 0.1, "b3_mg": 0.0, "b6_mg": 0.0, "vit_a_ug": 0.0, "azucar_g": 0.0, "vit_e_mg": 0.0, "vit_k_ug": 0.0, "vit_d_ug": 0.0, "selenio_ug": 0.1}'::jsonb, '{"texto": "1 pizca", "gramos": 0.5}'::jsonb, '[{"texto": "1 pizca", "gramos": 0.5}, {"texto": "1 cucharadita", "gramos": 6}, {"texto": "½ cucharadita", "gramos": 3}]'::jsonb, null, 'sal sal de cocina sal marina') on conflict (id) do update set nombre = excluded.nombre, sinonimos = excluded.sinonimos, categoria = excluded.categoria, fuente = excluded.fuente, por_100g = excluded.por_100g, porcion_base = excluded.porcion_base, porciones = excluded.porciones, busqueda = excluded.busqueda;
insert into public.alimentos (id, nombre, sinonimos, categoria, fuente, por_100g, porcion_base, porciones, foto_url, busqueda) values ('limon-exprimido', 'Jugo de limón', array['limón exprimido', 'zumo de limón', 'gotas de limón']::text[], 'condimentos', 'Jugo de limón recién exprimido. USDA sr_legacy · 167747', '{"vit_k_ug": 0.0, "vit_e_mg": 0.15, "colesterol_mg": 0.0, "b12_ug": 0.0, "vit_d_ug": 0.0, "vit_c_mg": 38.7, "b1_mg": 0.02, "b2_mg": 0.01, "folato_ug": 20.0, "vit_a_ug": 0.0, "proteina_g": 0.35, "grasa_sat_g": 0.04, "fibra_g": 0.3, "hierro_mg": 0.08, "magnesio_mg": 6.0, "fosforo_mg": 8.0, "sodio_mg": 1.0, "cobre_mg": 0.02, "manganeso_mg": 0.01, "b3_mg": 0.09, "b6_mg": 0.05, "azucar_g": 2.52, "calcio_mg": 6.0, "potasio_mg": 103.0, "zinc_mg": 0.05, "grasa_g": 0.24, "carbos_g": 6.9, "kcal": 22.0, "selenio_ug": 0.1}'::jsonb, '{"texto": "1 limón exprimido", "gramos": 30}'::jsonb, '[{"texto": "1 limón exprimido", "gramos": 30}, {"texto": "1 cucharada", "gramos": 15}, {"texto": "1 cucharadita", "gramos": 5}]'::jsonb, null, 'jugo de limon limon exprimido zumo de limon gotas de limon') on conflict (id) do update set nombre = excluded.nombre, sinonimos = excluded.sinonimos, categoria = excluded.categoria, fuente = excluded.fuente, por_100g = excluded.por_100g, porcion_base = excluded.porcion_base, porciones = excluded.porciones, busqueda = excluded.busqueda;
insert into public.alimentos (id, nombre, sinonimos, categoria, fuente, por_100g, porcion_base, porciones, foto_url, busqueda) values ('carne-cerdo', 'Carne de cerdo', array['cerdo', 'marrano', 'carne de marrano', 'cerdo asado', 'carne de chancho', 'pernil de cerdo']::text[], 'proteinas', 'Carne de cerdo cocida, con su grasa (pierna, lomo, brazo y costilla). USDA sr_legacy · 168297', '{"proteina_g": 26.36, "fibra_g": 0.0, "hierro_mg": 1.11, "magnesio_mg": 24.0, "sodio_mg": 57.0, "cobre_mg": 0.09, "manganeso_mg": 0.01, "vit_a_ug": 2.0, "vit_d_ug": 0.9, "vit_c_mg": 0.1, "b1_mg": 0.61, "b2_mg": 0.29, "folato_ug": 2.0, "b12_ug": 0.7, "vit_k_ug": 0.0, "colesterol_mg": 88.0, "grasa_sat_g": 4.89, "grasa_g": 13.89, "carbos_g": 0.0, "kcal": 238.0, "azucar_g": 0.0, "calcio_mg": 20.0, "potasio_mg": 341.0, "zinc_mg": 3.06, "selenio_ug": 42.0, "vit_e_mg": 0.13, "b3_mg": 6.05, "b6_mg": 0.54, "fosforo_mg": 221.0}'::jsonb, '{"texto": "1 porción", "gramos": 120}'::jsonb, '[{"texto": "1 porción", "gramos": 120}, {"texto": "1 trozo pequeño", "gramos": 60}, {"texto": "100 g", "gramos": 100}]'::jsonb, null, 'carne de cerdo cerdo marrano carne de marrano cerdo asado carne de chancho pernil de cerdo') on conflict (id) do update set nombre = excluded.nombre, sinonimos = excluded.sinonimos, categoria = excluded.categoria, fuente = excluded.fuente, por_100g = excluded.por_100g, porcion_base = excluded.porcion_base, porciones = excluded.porciones, busqueda = excluded.busqueda;
update public.alimentos set busqueda = busqueda || ' marrano' where id in ('lomo-cerdo', 'chuleta-cerdo', 'costilla-cerdo', 'chicharron') and busqueda not like '%marrano%';
